import { describeNoticeMonths } from './lienNoticeMonthWords.ts'
import { workMonthLabel } from './forecastWorkMonths.ts'
import { calendarYmdInAppTzFromIso } from '../../utils/dateUtils.ts'

/**
 * The months an affidavit swears, set by hand (v2.7270, punch list #356 part 2, the owner's door 1 of 2026-11-14). Pure.
 *
 * The short form names the months the job's recorded § 53.056 notices name, cut to the job's own work span. When the
 * notice on record names other months the paper prints a blank, and since v2.7266 says why. Counsel's word on these jobs
 * was that they may rely on the notice because its total included them; the app cannot read that month by month. So a
 * person picks the months the paper swears and types counsel's reason, who said it and when, as the claim set by hand
 * works (`lienClaimCorrection.ts`). The record stays per job (`job_lien_affidavit_months`), the paper prints the picked
 * months, the help sheet names them as set by hand with the reason, and the attorney line still reads each month
 * against the record. The words a sworn paper uses are counsel's, never the app's.
 */
export type LienAffidavitMonthsByHand = {
  jobId: string
  /** 'YYYY-MM', oldest first. */
  months: string[]
  reason: string
  setByName: string
  /** ISO, as the row keeps it. */
  setAt: string
}

const MONTH_KEY = /^\d{4}-(0[1-9]|1[0-2])$/

/** The table row → the kernel's shape; null for a row with no job or no month. */
export function parseLienAffidavitMonthsByHand(row: unknown): LienAffidavitMonthsByHand | null {
  const r = row as { job_id?: unknown; months?: unknown; reason?: unknown; set_by_name?: unknown; set_at?: unknown } | null
  if (!r || typeof r.job_id !== 'string') return null
  const months = lienAffidavitMonthsCleaned(Array.isArray(r.months) ? r.months : [])
  if (months.length === 0) return null
  return { jobId: r.job_id, months, reason: typeof r.reason === 'string' ? r.reason : '', setByName: typeof r.set_by_name === 'string' ? r.set_by_name : '', setAt: typeof r.set_at === 'string' ? r.set_at : '' }
}

/** Month keys only, each once, oldest first. */
export function lienAffidavitMonthsCleaned(months: ReadonlyArray<unknown>): string[] {
  return [...new Set(months.filter((m): m is string => typeof m === 'string' && MONTH_KEY.test(m)))].sort()
}

/** A month typed by hand, 'YYYY-MM' or 'MM/YYYY' or 'Sep 2026', as a key; '' when it is not a month. */
export function lienAffidavitMonthKeyFromText(text: string): string {
  const t = text.trim()
  if (MONTH_KEY.test(t)) return t
  const slash = /^(\d{1,2})\/(\d{4})$/.exec(t)
  if (slash) {
    const m = Number(slash[1])
    return m >= 1 && m <= 12 ? `${slash[2]}-${String(m).padStart(2, '0')}` : ''
  }
  const words = /^([A-Za-z]{3,9})\.?\s+(\d{4})$/.exec(t)
  if (words) {
    const names = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec']
    const i = names.indexOf(words[1]!.slice(0, 3).toLowerCase())
    return i >= 0 ? `${words[2]}-${String(i + 1).padStart(2, '0')}` : ''
  }
  return ''
}

export type LienAffidavitMonthChoice = { key: string; label: string; /** Where the month comes from: the job's own work, the notice on record, both, or a month a person added. */ from: 'work' | 'notice' | 'both' | 'added' }

/** The months the editor offers to tick: the job's own work months, the notice's months and the months already set, each once, oldest first. */
export function lienAffidavitMonthChoices(input: { work: ReadonlyArray<string>; named: ReadonlyArray<string>; current: ReadonlyArray<string> }): LienAffidavitMonthChoice[] {
  const work = new Set(lienAffidavitMonthsCleaned(input.work))
  const named = new Set(lienAffidavitMonthsCleaned(input.named))
  const all = lienAffidavitMonthsCleaned([...input.work, ...input.named, ...input.current])
  return all.map((key) => ({ key, label: workMonthLabel(key), from: work.has(key) && named.has(key) ? 'both' : work.has(key) ? 'work' : named.has(key) ? 'notice' : 'added' }))
}

/** The small word beside a choice: where the month comes from. */
export function lienAffidavitMonthChoiceWords(from: LienAffidavitMonthChoice['from']): string {
  return from === 'both' ? 'worked · on the notice' : from === 'work' ? 'worked' : from === 'notice' ? 'on the notice' : 'added by hand'
}

/** Why the editor cannot save, or null when it can: at least one month, and counsel's reason. */
export function lienAffidavitMonthsByHandProblem(months: ReadonlyArray<string>, reason: string): string | null {
  if (lienAffidavitMonthsCleaned(months).length === 0) return 'Tick at least one month.'
  if (!reason.trim()) return 'Type counsel’s reason: who said the paper may name these months, and when.'
  return null
}

/** The save press's words: the verb and the count, as `countedLabel` would say them. */
export function lienAffidavitMonthsByHandSaveWords(months: ReadonlyArray<string>): string {
  const n = lienAffidavitMonthsCleaned(months).length
  return n === 0 ? 'Set the months by hand' : `Set ${n} ${n === 1 ? 'month' : 'months'} by hand`
}

/** "Months set by hand · Robert · Nov 14 · counsel's reason" — the pane's line, the window's and the help sheet's. */
export function lienAffidavitMonthsByHandWords(m: LienAffidavitMonthsByHand, formatDay: (ymd: string) => string): string {
  const when = m.setAt ? formatDay(calendarYmdInAppTzFromIso(m.setAt)) : ''
  return [`Months set by hand: ${describeNoticeMonths(m.months)}`, m.setByName.trim(), when, m.reason.trim()].filter(Boolean).join(' · ')
}

/** The help sheet's check row: the months, who set them and the reason, so the attorney reads it beside the notice check. */
export function lienAffidavitMonthsByHandCheck(m: LienAffidavitMonthsByHand, formatDay: (ymd: string) => string): { lead: string; words: string; row: string } {
  const when = m.setAt ? formatDay(calendarYmdInAppTzFromIso(m.setAt)) : ''
  const who = [m.setByName.trim(), when].filter(Boolean).join(' on ')
  return {
    lead: 'Months set by hand.',
    words: `The paper names ${describeNoticeMonths(m.months)}${who ? `, set by ${who}` : ''}. The reason given: ${m.reason.trim()}`,
    row: `Months set by hand: ${describeNoticeMonths(m.months)}.`,
  }
}
